	@Test
	void correlatedKernelPricesOneSharedExpressionLikeAnExplicitAlias() {
		compareKernelExpressionCosts(false);
	}

	@Test
	void delegatedLateralKeepsItsOwnExpressionCosts() {
		compareKernelExpressionCosts(true);
	}

	private void compareKernelExpressionCosts(boolean lateral) {
		LmdbStore store = new LmdbStore(dataDir.toFile(), new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (SailRepositoryConnection connection = repository.getConnection()) {
				ValueFactory vf = connection.getValueFactory();
				connection.begin();
				for (int index = 0; index < 3; index++) {
					var subject = vf.createIRI("urn:scalar:subject:" + index);
					connection.add(subject, vf.createIRI("urn:scalar:name"), vf.createLiteral("NAME" + index));
					if (index != 0) {
						connection.add(subject, vf.createIRI("urn:scalar:tag"), vf.createLiteral("first"));
						connection.add(subject, vf.createIRI("urn:scalar:tag"), vf.createLiteral("second"));
					}
				}
				connection.commit();
			}
			assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
			String expression = "STRLEN(LCASE(STR(?name)))";
			LmdbNativeCostVector alias = correlatedQuote(repository, expression, "?first", lateral);
			LmdbNativeCostVector shared = correlatedQuote(repository, expression, expression, lateral);
			if (lateral) {
				assertThat(shared.expected(Feature.INTERPRETED_ROW))
						.as("the delegated native LATERAL body executes both expression copies")
						.isGreaterThan(alias.expected(Feature.INTERPRETED_ROW));
				assertThat(shared.expected(Feature.DECODED_ROW)).isGreaterThan(alias.expected(Feature.DECODED_ROW));
			} else {
				assertThat(shared.expected(Feature.INTERPRETED_ROW))
						.as("a common expression uses one callback followed by an alias in the admitted kernel")
						.isEqualTo(alias.expected(Feature.INTERPRETED_ROW));
				assertThat(shared.expected(Feature.DECODED_ROW)).isEqualTo(alias.expected(Feature.DECODED_ROW));
			}
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbNativeCostVector correlatedQuote(SailRepository repository, String first, String second,
			boolean lateral) {
		String previousSync = System.setProperty(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY, "true");
		String previousThreshold = System.setProperty(LmdbNativeJaninoCodegen.THRESHOLD_ROWS_PROPERTY, "0");
		List<LmdbNativeDecisionRecord.Entry> selected = new ArrayList<>();
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			if (record.winner() >= 0 && "irAggregate".equals(record.winnerId())) {
				selected.add(record.entries().get(record.winner()));
			}
		});
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(
					"SELECT (SUM(?first) AS ?a) (SUM(?second) AS ?b) WHERE { "
							+ "?s <urn:scalar:name> ?name . OPTIONAL { ?s <urn:scalar:tag> ?tag } "
							+ (lateral ? "LATERAL { " : "")
							+ "BIND(" + first + " AS ?first) BIND(" + second + " AS ?second) "
							+ (lateral ? "} " : "") + "}");
			query.setForcedLmdbExecutionStrategy("irAggregate");
			try (TupleQueryResult result = query.evaluate()) {
				assertThat(result.hasNext()).isTrue();
				var bindings = result.next();
				assertThat(bindings.getValue("a").stringValue()).isEqualTo("25");
				assertThat(bindings.getValue("a")).isEqualTo(bindings.getValue("b"));
				assertThat(result.hasNext()).isFalse();
			}
		} finally {
			LmdbNativeDispatchLoop.observeSelections(null);
			restoreProperty(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY, previousSync);
			restoreProperty(LmdbNativeJaninoCodegen.THRESHOLD_ROWS_PROPERTY, previousThreshold);
		}
		assertThat(selected).hasSize(1);
		return selected.getFirst().features();
	}

	private static void restoreProperty(String name, String previous) {
		if (previous == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, previous);
		}
	}

	@Test
	void aliasesKeepTheirExistingAssignmentCost() {
		CopyBinding[] copies = { CopyBinding.slot(1, 0) };
		assertThat(NativeScalarCosts.additionalCopies(copies).isZero()).isTrue();
		assertThat(NativeScalarCosts.copies(copies).expected(Feature.INTERPRETED_ROW)).isEqualTo(1D);
	}

	@Test
	void nestedLexicalDispatchesAndSharedDictionaryReadsAreDistinct() {
		ValueExpr expression = new FunctionCall(FN.CONCAT.stringValue(),
				new FunctionCall(FN.LOWER_CASE.stringValue(), new Str(new Var("a"))),
				new FunctionCall(FN.UPPER_CASE.stringValue(), new Str(new Var("a"))));
		LmdbNativeCostVector work = NativeScalarCosts.additionalCopies(new CopyBinding[] { copy(expression) });
		assertThat(work.expected(Feature.INTERPRETED_ROW)).isEqualTo(5D);
		assertThat(work.expected(Feature.DECODED_ROW)).isEqualTo(1D);
		assertThat(work.low(Feature.INTERPRETED_ROW)).isZero();
		assertThat(work.high(Feature.INTERPRETED_ROW)).isInfinite();
	}

