	@Test
	void delegatedWitnessStillPaysForItsOwnCallbacks() {
		RowState row = row(new StatsSource(100L));
		SlotPlan simple = new FilterPlan(values(3), new ExistsFilter(new ExtensionPlan(values(1),
				new CopyBinding[] { copy(new Var("a")) })), 1L);
		SlotPlan lexical = new FilterPlan(values(3), new ExistsFilter(new ExtensionPlan(values(1),
				new CopyBinding[] { copy(lexical()) })), 1L);
		LmdbNativeKernelBindings.BindHook[] outerHooks = new LmdbNativeKernelBindings.BindHook[0];
		LmdbNativeCostVector baseline = LmdbNativePlanExecutionProfile.kernelVector(simple, row, 0L,
				Feature.GENERATED_ROW, outerHooks);
		LmdbNativeCostVector actual = LmdbNativePlanExecutionProfile.kernelVector(lexical, row, 0L,
				Feature.GENERATED_ROW, outerHooks);
		assertThat(actual.expected(Feature.INTERPRETED_ROW)).isGreaterThan(baseline.expected(Feature.INTERPRETED_ROW));
		assertThat(actual.expected(Feature.DECODED_ROW)).isGreaterThan(baseline.expected(Feature.DECODED_ROW));
		assertThat(actual.expected(Feature.INTERPRETED_ROW) - baseline.expected(Feature.INTERPRETED_ROW))
				.as("three shared scalar dispatches per dictionary read, regardless of the enclosing execution tier")
				.isCloseTo(3D * (actual.expected(Feature.DECODED_ROW) - baseline.expected(Feature.DECODED_ROW)),
						offset(1e-10));
	}

