	private static ValueExpr lexical() {
		return new FunctionCall(FN.STRING_LENGTH.stringValue(),
				new FunctionCall(FN.LOWER_CASE.stringValue(), new Str(new Var("a"))));
	}

	private static CopyBinding copy(ValueExpr expression) {
		NativeScalarPlan scalar = NativeScalarPlan.value(expression, name -> 0, false, 0L, false, false);
		return CopyBinding.computedValue(1, new LmdbNativeCompiledValue(1L, ignored -> null, scalar), true);
	}

	private static ValuesPlan values(int count) {
		ValuesRow[] rows = new ValuesRow[count];
		for (int index = 0; index < count; index++) {
			rows[index] = new ValuesRow(new int[] { 0 }, new long[] { index + 1L });
		}
		return new ValuesPlan(rows);
	}
